() => {
        const isVisible = selector => {
          const element = document.querySelector(selector);
          if (!element) return false;
          const style = window.getComputedStyle(element);
          if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) {
            return false;
          }
          const rect = element.getBoundingClientRect();
          return rect.width > 0 && rect.height > 0;
        };
        const errorVisible = isVisible('.error-screen');
        const inactiveVisible = isVisible('[data-testid="inactive-tab-screen"]');
        const viewVisible = isVisible('.view-wrapper') || isVisible('nav[aria-label="Account workspace"]') || isVisible('[data-testid="account-workspace-mobile-toggle"]') || isVisible('[data-testid="app-runtime-ready"]');
        const runtimeCreationVisible = isVisible('#runtime-creation') || isVisible('.brainvault-wrapper') || isVisible('.quick-login-grid') || Boolean(Array.from(document.querySelectorAll('button')).find(button => {
          const label = (button.textContent || '').trim().toLowerCase();
          return label === 'alice' || label === 'bob' || label === 'carol' || label === 'dave';
        }));
        return !errorVisible && !inactiveVisible && (viewVisible || runtimeCreationVisible);
      }
